+				} break;
+				case ScriptLanguage::REFACTOR_RENAME_SYMBOL_RESULT_KEYWORD: {
+					symbol_color = EDITOR_GET("text_editor/theme/highlighting/keyword_color");
+				} break;
+				case ScriptLanguage::REFACTOR_RENAME_SYMBOL_RESULT_CLASS_NAME: {
